mod solution;

fn main() {
    let cases = [
    (r#"base=3 exp=13 mod=1000"#, r#"323"#),
    (r#"base=2 exp=5 mod=13"#, r#"6"#),
    (r#"
base=2 exp=5 mod=13
"#, r#"6"#),
    (r#"  
base=3 exp=13 mod=1000
  "#, r#"323"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS fast-power");
}
